bool Codec<ChangeTrustAsset>::encode(const ChangeTrustAsset& v, Encoder& e) {
  switch (v.t_) {
    case AssetType::ASSET_TYPE_NATIVE:
      return e.i32(static_cast<std::int32_t>(v.t_));
    case AssetType::ASSET_TYPE_CREDIT_ALPHANUM4:
      if (const auto* p = std::get_if<1>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ChangeTrustAsset: payload does not match discriminant");
    case AssetType::ASSET_TYPE_CREDIT_ALPHANUM12:
      if (const auto* p = std::get_if<2>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ChangeTrustAsset: payload does not match discriminant");
    case AssetType::ASSET_TYPE_POOL_SHARE:
      if (const auto* p = std::get_if<3>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ChangeTrustAsset: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "ChangeTrustAsset: unknown discriminant");
  }
}

bool Codec<ChangeTrustAsset>::decode(ChangeTrustAsset& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 0:
      v.t_ = static_cast<AssetType>(tag);
      v.v_.template emplace<0>();
      return true;
    case 1:
      v.t_ = static_cast<AssetType>(tag);
      v.v_.template emplace<1>();
      return d.field("alphaNum4", std::get<1>(v.v_));
    case 2:
      v.t_ = static_cast<AssetType>(tag);
      v.v_.template emplace<2>();
      return d.field("alphaNum12", std::get<2>(v.v_));
    case 3:
      v.t_ = static_cast<AssetType>(tag);
      v.v_.template emplace<3>();
      return d.field("liquidityPool", std::get<3>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "ChangeTrustAsset: unknown discriminant");
  }
}

bool Codec<ChangeTrustAsset>::gen(ChangeTrustAsset& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 0 : r.index(4);
  switch (i) {
    case 0: {
      v.t_ = AssetType::ASSET_TYPE_NATIVE;
      v.v_.template emplace<0>();
      return true;
    }
    case 1: {
      v.t_ = AssetType::ASSET_TYPE_CREDIT_ALPHANUM4;
      auto& p = v.v_.template emplace<1>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 2: {
      v.t_ = AssetType::ASSET_TYPE_CREDIT_ALPHANUM12;
      auto& p = v.v_.template emplace<2>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 3: {
      v.t_ = AssetType::ASSET_TYPE_POOL_SHARE;
      auto& p = v.v_.template emplace<3>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

