const char* enum_name(PreconditionType v) noexcept {
  switch (v) {
    case PreconditionType::PRECOND_NONE: return "PRECOND_NONE";
    case PreconditionType::PRECOND_TIME: return "PRECOND_TIME";
    case PreconditionType::PRECOND_V2: return "PRECOND_V2";
    default: return nullptr;
  }
}
bool enum_from_name(std::string_view s, PreconditionType& v) noexcept {
  if (s == "PRECOND_NONE") { v = PreconditionType::PRECOND_NONE; return true; }
  if (s == "PRECOND_TIME") { v = PreconditionType::PRECOND_TIME; return true; }
  if (s == "PRECOND_V2") { v = PreconditionType::PRECOND_V2; return true; }
  return false;
}

bool Codec<PreconditionType>::encode(const PreconditionType& v, Encoder& e) {
  switch (v) {
    case PreconditionType::PRECOND_NONE:
    case PreconditionType::PRECOND_TIME:
    case PreconditionType::PRECOND_V2:
      break;
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "unknown enum value");
  }
  return e.i32(static_cast<std::int32_t>(v));
}
bool Codec<PreconditionType>::decode(PreconditionType& v, Decoder& d) {
  std::int32_t x;
  if (!d.i32(x)) return false;
  switch (x) {
    case 0: v = PreconditionType::PRECOND_NONE; return true;
    case 1: v = PreconditionType::PRECOND_TIME; return true;
    case 2: v = PreconditionType::PRECOND_V2; return true;
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "unknown enum value");
  }
}
bool Codec<PreconditionType>::gen(PreconditionType& v, XdrRng& r, std::uint32_t) {
  switch (r.index(3)) {
    case 0: v = PreconditionType::PRECOND_NONE; return true;
    case 1: v = PreconditionType::PRECOND_TIME; return true;
    case 2: v = PreconditionType::PRECOND_V2; return true;
  }
  v = PreconditionType::PRECOND_NONE;
  return true;
}

bool Codec<Preconditions>::encode(const Preconditions& v, Encoder& e) {
  switch (v.t_) {
    case PreconditionType::PRECOND_NONE:
      return e.i32(static_cast<std::int32_t>(v.t_));
    case PreconditionType::PRECOND_TIME:
      if (const auto* p = std::get_if<1>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "Preconditions: payload does not match discriminant");
    case PreconditionType::PRECOND_V2:
      if (const auto* p = std::get_if<2>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "Preconditions: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "Preconditions: unknown discriminant");
  }
}

bool Codec<Preconditions>::decode(Preconditions& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 0:
      v.t_ = static_cast<PreconditionType>(tag);
      v.v_.template emplace<0>();
      return true;
    case 1:
      v.t_ = static_cast<PreconditionType>(tag);
      v.v_.template emplace<1>();
      return d.field("timeBounds", std::get<1>(v.v_));
    case 2:
      v.t_ = static_cast<PreconditionType>(tag);
      v.v_.template emplace<2>();
      return d.field("v2", std::get<2>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "Preconditions: unknown discriminant");
  }
}

bool Codec<Preconditions>::gen(Preconditions& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 0 : r.index(3);
  switch (i) {
    case 0: {
      v.t_ = PreconditionType::PRECOND_NONE;
      v.v_.template emplace<0>();
      return true;
    }
    case 1: {
      v.t_ = PreconditionType::PRECOND_TIME;
      auto& p = v.v_.template emplace<1>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
    case 2: {
      v.t_ = PreconditionType::PRECOND_V2;
      auto& p = v.v_.template emplace<2>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

